MISSING = object()      # L7/L9/L10: the file is absent from the working tree
NA      = object()      # L7: inapplicable — the trim is not committed yet

ROOT = subprocess.run(["git", "rev-parse", "--show-toplevel"],
                      capture_output=True, text=True, check=True).stdout.strip()


def blob(ref):
    r = subprocess.run(["git", "show", ref], capture_output=True, cwd=ROOT)
    if r.returncode:
        sys.exit("cannot read %s: %s" % (ref, r.stderr.decode("utf-8", "replace").strip()))
    return r.stdout.decode("utf-8")          # bytes -> str; never $(...) which eats trailing newlines


def worktree(rel):
    with open("%s/%s" % (ROOT, rel), encoding="utf-8", newline="") as fh:
        return fh.read()


def added_at(rel):
    """The commit that ADDED `rel`, or "" if git does not know of one."""
    return subprocess.run(["git", "log", "--diff-filter=A", "-1", "--format=%H", "--", rel],
                          capture_output=True, text=True, cwd=ROOT).stdout.strip()


def scan(lines):
    inside = False
    for i, raw in enumerate(lines):
        s = raw.rstrip("\r\n")
        if s.startswith("```") or s.startswith("~~~"):
            yield i, s, inside
            inside = not inside
            continue
        yield i, s, inside


def zones(text):
    """-> (front, [record, ...], lines). A record is a heading-delimited BYTE SPAN, never a session."""
    lines = text.splitlines(keepends=True)
    st = [i for i, s, ins in scan(lines) if not ins and RECORD_START.match(s)]
    if not st:
        return text, [], lines
    front = "".join(lines[:st[0]])
    bounds = st + [len(lines)]
    return front, ["".join(lines[a:b]) for a, b in zip(st, bounds[1:])], lines


def label(rec):
    for ln in rec.splitlines():
        if ln.strip():
            return ln.strip()[:90]
    return "(empty record)"


def ids(recs):
    """The session id captured from each record's own heading line, in order."""
    return tuple(RECORD_START.match(r.splitlines()[0]).group(1) for r in recs)


def declared(before_front):
    """The front matter this trim is ALLOWED to produce, before the pointer is inserted."""
    for old, new in FRONT_SUBST:
        before_front = before_front.replace(old, new, 1)
    return before_front


# One canonical clause shape, so all three copies of the table parse with one regex. Bounds AND
# destination in a single match: parsing them separately is what let the third trim's first draft
# of L5 check the numbers of a table whose filenames were swapped.
ROUTE_CLAUSE = re.compile(r"\*\*(?:(\d+) ≤ N ≤ (\d+)|N ≤ (\d+)|N ≥ (\d+))\*\* → `([^`]+)`")


def parse_table(text):
    out = []
    for a, b, le, ge, dest in ROUTE_CLAUSE.findall(text):
        if a:
            out.append((int(a), int(b), dest))
        elif le:
            out.append((None, int(le), dest))
        else:
            out.append((int(ge), None, dest))
    return tuple(out)


_ID_CACHE = {}


def numeric_ids(dest, after, shard, sha):
    """The numeric session ids actually present in the file `dest` names. LIVE and SHARD come from
    the artifacts already in hand so a mutant can move them; the earlier shards are read once from
    the same commit as everything else. Non-numeric ids (`20B`, `20A`) are dropped, and a
    destination that yields none is reported rather than passing vacuously."""
    if dest == LIVE:
        text = after
    elif dest == SHARD.rsplit("/", 1)[1]:
        text = shard
    else:
        key = (dest, sha)
        if key not in _ID_CACHE:
            path = ARCHIVE_DIR + dest
            try:
                _ID_CACHE[key] = blob("%s:%s" % (sha, path)) if sha else worktree(path)
            except (SystemExit, OSError):
                _ID_CACHE[key] = None
        text = _ID_CACHE[key]
        if text is None:
            return None
    return sorted(int(i) for i in ids(zones(text)[1]) if i.isdigit())


# =====================================================================================
# The assertions. Each returns a list of failure strings; empty == holds.
# =====================================================================================

def L0(name, text):
    """footer_mode='none' asserted: no standalone `---` after the last record start may carry
    content below it. In a newest-on-top ledger the footer sits exactly where an oldest-first cut
    takes from, so 'none' must mean 'I looked', not 'I did not look'."""
    front, recs, lines = zones(text)
    if not recs:
        return ["L0 %s: no records found — grammar mismatch" % name]
    last = [i for i, s, ins in scan(lines) if not ins and RECORD_START.match(s)][-1]
    out = []
    for i, s, ins in scan(lines):
        if not ins and i > last and s.strip() == "---":
            tail = "".join(lines[i + 1:])
            if tail.strip():
                out.append("L0 %s: trailing file-scoped block at line %d (%d B): %.400s"
                           % (name, i + 1, len(tail.encode()), tail))
    return out


def L1(before_recs, after_recs, shard_recs):
    """Concatenation identity scoped to the RECORDS zone. Operand order is load-bearing: this
    ledger is newest-on-top and the cut takes from the bottom, so retained precedes archived. No
    invert step — TRANSFORM is None, which makes this the strongest form. This is the PRIMARY
    byte-level detector; L3 adds per-record naming on top of it, and L4-L12 see what both are
    blind to. It is ALSO what makes L2/b3's records half redundant — see the fifth trim's header,
    whose condition (TRANSFORM is None, L1 present) is re-checked at this cut and still holds."""
    got = "".join(after_recs) + "".join(shard_recs)
    want = "".join(before_recs)
    if got == want:
        return []
    i = next((n for n, (a, b) in enumerate(zip(got, want)) if a != b), min(len(got), len(want)))
    return ["L1: records-zone concatenation differs at character %d "
            "(retained+archived %d B vs before %d B)"
            % (i, len(got.encode()), len(want.encode()))]


def L2(before_front, after_front, shard_front, shard_recs, pointer):
    out = []
    # (a) footer half — inapplicable when FOOTER_MODE == "none"; say so, never claim it held.
    # (b) front-matter half. b1 is exact and subsumes b2; b2 and b3 still run because b1 is
    #     SKIPPED when the pointer is absent, and b3 is independent of all of it.
    for k, (old, _new) in enumerate(FRONT_SUBST, 1):
        if before_front.count(old) != 1:
            out.append("L2/b0 SUBSTITUTION %d NOT UNIQUELY ANCHORED: its source text occurs %d "
                       "times in the before front matter (want exactly 1) — the declaration has "
                       "gone stale against the file it claims to describe" % (k, before_front.count(old)))
    want_front = declared(before_front)
    if pointer not in after_front:
        out.append("L2_POINTER_MISSING: the declared pointer block is not in the live front matter "
                   "verbatim — a severed record set with no pointer to its shard")
    else:
        residue = after_front.replace(pointer, "", 1)
        if residue != want_front:
            i = next((n for n, (a, b) in enumerate(zip(residue, want_front)) if a != b),
                     min(len(residue), len(want_front)))
            out.append("L2/b1 CONFINEMENT: live front matter changed beyond the declared pointer "
                       "insertion + the %d declared substitutions; first divergence at character "
                       "%d (%d B residue vs %d B declared)"
                       % (len(FRONT_SUBST), i, len(residue.encode()), len(want_front.encode())))
    after_set = set(after_front.splitlines())
    for ln in want_front.splitlines():
        if ln.strip() and ln not in after_set:      # exact membership, never substring (BL-28)
            out.append("L2/b2 SURVIVAL: front-matter line vanished: %r" % ln[:120])
    # b3 NO-LEAK, narrowed to the BANNER by the fifth trim and carried forward unchanged. The
    # records half is pinned byte-for-byte by L1, so a front-matter line found there was already
    # there before the cut — history, not a leak — while the banner is new text L1 never sees and
    # L6 only compares against a declaration the same author wrote. `noleak_note()` prints what the
    # pre-narrowing predicate would have said, so nothing is hidden.
    for ln in before_front.splitlines():
        s = ln.strip()
        if len(s) > 24 and s in shard_front:
            out.append("L2/b3 NO-LEAK: front-matter line leaked into the shard's banner: %r" % s[:120])
    return out


def noleak_note(before_front, shard_recs):
    """NOT an assertion. The lines the pre-narrowing b3 would have flagged in the records half, so
    the narrowing hides nothing from a reader who wants to judge it."""
    body = "".join(shard_recs)
    return [(i, ln.strip()) for i, ln in enumerate(before_front.splitlines(), 1)
            if len(ln.strip()) > 24 and ln.strip() in body]


def L3(before_recs, after_recs, shard_recs):
    """Per-record partition by identity, ORDER and byte-equality. The injected set is MEASURED from
    record content, never baked in as a generation-time constant — that constant is why 5 of the 20
    proofs shipped across this fleet fail with zero data loss."""
    have = Counter(after_recs) + Counter(shard_recs)
    before_c = Counter(before_recs)
    absent = list((before_c - have).elements())
    added = list((have - before_c).elements())
    out = []
    for r in absent:
        out.append("L3 MISSING: a record from `before` is in neither artifact "
                   "(dropped, or edited so its original bytes exist nowhere): %s" % label(r))
    for r in added:
        # Project strengthening: this design forbids bundling any record edit into the trim commit
        # (three commits, by rule — claim, trim, close-out), so a non-zero added count means the
        # rule was broken. Deliberate divergence from the canonical tool, which downgraded this to
        # a note in v1.2.0 because the canonical repo bundles by practice.
        out.append("L3 ADDED: a record exists that was not in `before` — the trim commit "
                   "bundled a record edit: %s" % label(r))
    if not absent and not added:
        rebuilt, pool = [], Counter(added)
        for r in after_recs + shard_recs:
            if pool[r]:
                pool[r] -= 1
                continue
            rebuilt.append(r)
        bad = [i for i, (a, b) in enumerate(zip(before_recs, rebuilt)) if a != b]
        if bad or len(rebuilt) != len(before_recs):
            out.append("L3 ORDER: records out of order at indices %s" % bad[:12])
    return out


def L4(after_recs, shard_recs):
    """The cut point itself. L1 and L3 are blind to a whole-record boundary shift because it
    preserves concatenation, multiset membership and order simultaneously. This compares each side
    against the HAND-DECLARED cut key; reading the key back out of the artifacts would make it a
    restatement rather than an assertion."""
    out = []
    got_a, got_s = ids(after_recs), ids(shard_recs)
    if got_a != CUT_RETAINED:
        out.append("L4 CUT/retained: the live file holds Sessions %s; the declared cut key says %s"
                   % (list(got_a), list(CUT_RETAINED)))
    if got_s != CUT_ARCHIVED:
        out.append("L4 CUT/archived: the shard holds Sessions %s; the declared cut key says %s"
                   % (list(got_s), list(CUT_ARCHIVED)))
    return out


def L5(after_front, shard_front, claude, after, shard, sha, routing):
    """Routing coherence — see the third trim's proof for the full rationale. Everything above is
    about BYTES. This is about the sentence a human acts on: which file to open for Session N.
    Five layers, because each catches something the others cannot."""
    out = []
    lo_a, hi_a = min(map(int, CUT_ARCHIVED)), max(map(int, CUT_ARCHIVED))
    lo_r = min(map(int, CUT_RETAINED))
    shard_base = SHARD.rsplit("/", 1)[1]

    # (1) every prose copy of the table must parse to exactly the declaration — bounds AND file.
    for who, text in (("live pointer", after_front), ("shard banner", shard_front),
                      ("CLAUDE.md", claude)):
        got = parse_table(text)
        if got != routing:
            out.append("L5/1 %s: its routing table parses to %s; the declaration says %s"
                       % (who, list(got), list(routing)))

    # (2) the declaration must partition the session-id space: one open below, one open above,
    #     contiguous in between, no gap and no overlap.
    below = [c for c in routing if c[0] is None]
    above = [c for c in routing if c[1] is None]
    if len(below) != 1 or len(above) != 1 or routing[0][0] is not None or routing[-1][1] is not None:
        out.append("L5/2 shape: want exactly one open-below clause first and one open-above clause "
                   "last; got %d and %d in %s" % (len(below), len(above), list(routing)))
    else:
        edge = routing[0][1]
        for lo, hi, dest in routing[1:-1]:
            if lo != edge + 1:
                out.append("L5/2 %s at %d-%d (`%s`): the preceding clause ends at %d"
                           % ("GAP" if lo > edge + 1 else "OVERLAP", lo, hi, dest, edge))
            edge = hi
        if routing[-1][0] != edge + 1:
            out.append("L5/2 %s between the last range (ends %d) and `N >= %d` (`%s`)"
                       % ("GAP" if routing[-1][0] > edge + 1 else "OVERLAP", edge,
                          routing[-1][0], routing[-1][2]))

    # (3) the clause naming THIS shard must be exactly this cut's archived span, and the clause
    #     naming the live ledger must open exactly at this cut's retained floor.
    mine = [c for c in routing if c[2] == shard_base]
    live = [c for c in routing if c[2] == LIVE]
    if len(mine) != 1 or mine[0][:2] != (lo_a, hi_a):
        out.append("L5/3 shard clause: the table routes %s to `%s`; this cut archived Sessions "
                   "%d-%d" % ([c[:2] for c in mine], shard_base, lo_a, hi_a))
    if len(live) != 1 or live[0][:2] != (lo_r, None):
        out.append("L5/3 live clause: the table routes %s to `%s`; this cut retained Sessions "
                   "%d and up" % ([c[:2] for c in live], LIVE, lo_r))

    # (4) THE ANCHOR AGAINST REALITY. A declaration can be wrong in a way that is perfectly
    #     self-consistent — move a boundary in every copy at once and (1)-(3) all still hold. So
    #     open each file the table names and check what is actually in it.
    for lo, hi, dest in routing:
        found = numeric_ids(dest, after, shard, sha)
        if found is None:
            out.append("L5/4 `%s`: the table routes Sessions %s-%s here and the file cannot be "
                       "read" % (dest, lo, hi))
            continue
        if not found:
            out.append("L5/4 `%s`: no numeric session ids found — the check would pass vacuously"
                       % dest)
            continue
        stray = [n for n in found if (lo is not None and n < lo) or (hi is not None and n > hi)]
        if stray:
            out.append("L5/4 `%s`: routed Sessions %s-%s, but it actually contains %s (ids %d-%d)"
                       % (dest, lo, hi, stray[:8], found[0], found[-1]))
    return out


def L6(shard_front, banner):
    """The shard banner, pinned byte-for-byte — the shard-side analogue of L2/b1. Without it the
    banner is the one part of the shard that is neither frozen nor checked, while its own text says
    provenance is proved here."""
    if shard_front == banner:
        return []
    i = next((n for n, (a, b) in enumerate(zip(shard_front, banner)) if a != b),
             min(len(shard_front), len(banner)))
    return ["L6 BANNER: the shard's banner is not the declared text; first divergence at character "
            "%d (%d B in the shard vs %d B declared)"
            % (i, len(shard_front.encode()), len(banner.encode()))]


def L7(sha, shard_blob, disk):
    """Write-once, enforced, for THIS shard. Everything else reads history at the trim commit, so
    the suite stays green through any later truncation or deletion of it. Asymmetric on purpose:
    the live ledger is SUPPOSED to change and is never compared this way.

    Applicability is decided by `disk` ALONE and never by `sha` — see the third trim's proof for
    why a stand-in sha makes every mutant 'caught' for the wrong reason."""
    if disk is NA:
        return []                      # not committed yet; the run banner says so rather than
                                       # letting silence read as a pass
    if disk is MISSING:
        return ["L7 WRITE-ONCE: the shard is GONE from the working tree. Every assertion above "
                "still passes because they read git history at the trim commit — this one is the "
                "reason you found out."]
    if disk != shard_blob:
        i = next((n for n, (a, b) in enumerate(zip(disk, shard_blob)) if a != b),
                 min(len(disk), len(shard_blob)))
        return ["L7 WRITE-ONCE: the shard on disk is not the shard committed at %s; first "
                "divergence at character %d (%d B on disk vs %d B committed). Shards are "
                "write-once; this file was edited after its trim."
                % (sha[:7] if sha else "the trim commit", i,
                   len(disk.encode()), len(shard_blob.encode()))]
    return []


def L8(reach_texts, routing):
    """The copies that live outside every earlier proof. Both halves matter and neither subsumes
    the other: the hand-declared strings catch a stale COUNT WORD, which is prose and invisible to
    any derived check; the ROUTING-derived set catches a shard left out or a phantom one, without
    restating the list a second time and giving it a second chance to go stale.

    `routing` is the DECLARED table, taken from the same override L5 reads — never the module-level
    constant, which is the fourth trim's bug the fifth fixed and measured."""
    out = []
    want_names = {d for _lo, _hi, d in routing if d != LIVE}
    for path, required, forbidden in REACH:
        text = reach_texts.get(path)
        if text is None:
            out.append("L8 `%s`: unreadable, so no copy of the shard set in it can be checked"
                       % path)
            continue
        for s in required:
            if s not in text:
                out.append("L8/required `%s`: this trim declares it must contain %r and it does "
                           "not — the copy no earlier proof could reach is now stale" % (path, s[:90]))
        for s in forbidden:
            if s in text:
                out.append("L8/forbidden `%s`: it still contains %r, which this trim falsified"
                           % (path, s[:90]))
        got_names = set(SHARD_NAME.findall(text))
        if got_names != want_names:
            out.append("L8/set `%s`: it names shards %s; ROUTING names %s (missing %s; unknown %s)"
                       % (path, sorted(got_names), sorted(want_names),
                          sorted(want_names - got_names) or "none",
                          sorted(got_names - want_names) or "none"))
    return out


def L9(lineage):
    """Write-once for the WHOLE lineage, not just the shard this proof shipped with. Each ancestor
    is compared against the blob committed at the commit that ADDED it — its own commit, never this
    trim's — so this is applicable from the first run, before this trim is committed at all."""
    out = []
    for path, committed, disk in lineage:
        if committed is None:
            out.append("L9 `%s`: git knows no commit that added it, so there is nothing to hold "
                       "the working tree against" % path)
            continue
        if disk is MISSING:
            out.append("L9 WRITE-ONCE `%s`: GONE from the working tree. The routing table still "
                       "sends readers here and every byte assertion above still passes, because "
                       "they read history." % path)
            continue
        if disk != committed:
            i = next((n for n, (a, b) in enumerate(zip(disk, committed)) if a != b),
                     min(len(disk), len(committed)))
            out.append("L9 WRITE-ONCE `%s`: on disk it is not the file that was committed; first "
                       "divergence at character %d (%d B on disk vs %d B committed). Shards are "
                       "write-once — this one was edited after its own trim."
                       % (path, i, len(disk.encode()), len(committed.encode())))
    return out


def L10(provenance):
    """The ancestors' PROOFS, held against hand-declared freeze commits. L9 holds the shards
    because that is a precondition for running their proofs; this holds the proofs, which is the
    other one. A weakened ancestor proof is worse than a deleted one: it still exits 0."""
    out = []
    for path, freeze, committed, disk in provenance:
        if committed is None:
            out.append("L10 `%s`: the declared freeze commit %s does not hold this path, so there "
                       "is nothing to compare the working tree against — the declaration is wrong, "
                       "or the history was rewritten" % (path, freeze[:7]))
            continue
        if disk is MISSING:
            out.append("L10 PROVENANCE `%s`: GONE from the working tree. Its shard is still here "
                       "and L9 still passes on it; six banners and a routing table still tell "
                       "readers to run this proof, and there is nothing left to run." % path)
            continue
        if disk != committed:
            i = next((n for n, (a, b) in enumerate(zip(disk, committed)) if a != b),
                     min(len(disk), len(committed)))
            out.append("L10 PROVENANCE `%s`: on disk it is not the proof frozen at %s; first "
                       "divergence at character %d (%d B on disk vs %d B frozen). An ancestor "
                       "proof was edited after its session ended — if that edit weakened it, it "
                       "still exits 0."
                       % (path, freeze[:7], i, len(disk.encode()), len(committed.encode())))
    return out


def L11(before, after, after_recs, claude, policy):
    """The retention rule this cut exists to satisfy. L0-L10 all ask whether the trim was performed
    FAITHFULLY; none asks whether it was performed AT ALL. A one-record trim is perfectly lossless
    and leaves the file over the trigger that fired it."""
    trigger, target, floor, texts = policy
    out = []
    nb, na = len(before.splitlines()), len(after.splitlines())
    if nb <= trigger:
        out.append("L11/fire: the live file was %d lines before this cut; the declared trigger is "
                   "more than %d, so this trim should not have fired" % (nb, trigger))
    if na > target:
        out.append("L11/target: the live file is %d lines after this cut; the declared target is "
                   "at most %d — the cut was too shallow to solve the problem that fired it"
                   % (na, target))
    if len(after_recs) < floor:
        out.append("L11/floor: the live file retains %d records; the declared floor is %d — the "
                   "cut was too deep and took working context with it" % (len(after_recs), floor))
    for s in texts:
        if s not in claude:
            out.append("L11/declared: `CLAUDE.md` no longer states %r, so the numbers this "
                       "assertion enforces are no longer the numbers the project declares" % s[:90])
    return out


def L12(after_front, shard_front, shard, after_recs, shard_recs, reach_texts, sizes, prose):
    """ARITHMETIC. Every number this trim states about the SIZE of its own artifacts, derived from
    the artifacts and held against the prose that states it. New at the sixth trim; the hole it
    closes is this lineage's own — see the header for the measurement.

    Two halves, and they are independent. The NUMERIC half (headings/lines/total/cap) compares the
    declared integers against the artifacts. The PROSE half compares those same integers against
    the formatted figures printed in five texts, in two formats, because this project's prose
    writes small counts as words and large ones as digits. Neither half can be satisfied by the
    other: a wrong integer passes the prose half if the prose repeats it, and correct integers pass
    the numeric half while a stale sentence still misinforms a reader."""
    out = []
    measured = {
        "archived_headings": len(shard_recs),
        "archived_lines":    len("".join(shard_recs).splitlines()),
        "shard_total":       len(shard.splitlines()),
        "retained_records":  len(after_recs),
        # READ_CAP is a property of the agent harness, not of this repository; there is nothing
        # here to measure it against, so it is declared-only and used solely by the cap arm below.
        "read_cap":          sizes["read_cap"],
        # The mutant count lives in the self-test, which a plain run does not build; the self-test
        # asserts it against len(mutants) itself. Declared-only here for the same honest reason.
        "mutants":           sizes["mutants"],
    }
    for key in ("archived_headings", "archived_lines", "shard_total", "retained_records"):
        if sizes[key] != measured[key]:
            out.append("L12/%s: this trim declares %s = %d; the artifacts measure %d — a figure "
                       "was typed rather than derived"
                       % (key, key, sizes[key], measured[key]))
    if measured["shard_total"] >= sizes["read_cap"]:
        out.append("L12/cap: the shard is %d lines and the declared agent read cap is %d — the "
                   "banner's claim that it sits under the cap is false, and a `Read` of it "
                   "truncates in silence" % (measured["shard_total"], sizes["read_cap"]))
    texts = {"live pointer": after_front, "shard banner": shard_front}
    texts.update(reach_texts)
    for where, literal, form, keys in prose:
        text = texts.get(where)
        if text is None:
            out.append("L12/prose `%s`: unreadable, so the size figures in it cannot be checked"
                       % where)
            continue
        if literal not in text:
            out.append("L12/prose `%s`: this trim declares it states %r and it does not — the "
                       "sentence and the artifact have diverged" % (where, literal[:90]))
            continue
        for key in keys:
            want = WORDS.get(measured[key]) if form == "word" else "{:,}".format(measured[key])
            if want is None or want not in literal:
                out.append("L12/prose `%s`: %r claims %s but the artifacts measure %s (%r) — the "
                           "prose is stated in a figure nobody derived"
                           % (where, literal[:70], key, measured[key], want))
    return out


def check(before, after, shard, claude, sha, disk, reach_texts, lineage, provenance, decl=None):
    d = {"POINTER": POINTER, "BANNER": BANNER, "ROUTING": ROUTING, "POLICY": POLICY,
         "SIZES": SIZES, "SIZE_PROSE": SIZE_PROSE}
    if decl:
        d.update(decl)
    bf, br, _ = zones(before)
    af, ar, _ = zones(after)
    sf, sr, _ = zones(shard)
    fails = []
    fails += L0("before", before) + L0("after", after) + L0("shard", shard)
    fails += L1(br, ar, sr)
    fails += L2(bf, af, sf, sr, d["POINTER"])
    fails += L3(br, ar, sr)
    fails += L4(ar, sr)
    fails += L5(af, sf, claude, after, shard, sha, d["ROUTING"])
    fails += L6(sf, d["BANNER"])
    fails += L7(sha, shard, disk)
    fails += L8(reach_texts, d["ROUTING"])
    fails += L9(lineage)
    fails += L10(provenance)
    fails += L11(before, after, ar, claude, d["POLICY"])
    fails += L12(af, sf, shard, ar, sr, reach_texts, d["SIZES"], d["SIZE_PROSE"])
    return fails, (br, ar, sr)


# =====================================================================================
def artifacts():
    sha = added_at(SHARD)

    # L9's operands never depend on `sha`: each ancestor is held against ITS OWN add-commit.
    lineage = []
    for path in ANCESTORS:
        a = added_at(path)
        committed = blob("%s:%s" % (a, path)) if a else None
        try:
            on_disk = worktree(path)
        except OSError:
            on_disk = MISSING
        lineage.append((path, committed, on_disk))
    lineage = tuple(lineage)

    # L10's operands never depend on `sha` either: each ancestor proof is held against its own
    # HAND-DECLARED freeze commit, so this is applicable before the trim is committed at all.
    provenance = []
    for path, freeze in ANCESTOR_PROOFS:
        try:
            committed = blob("%s:%s" % (freeze, path))
        except SystemExit:
            committed = None
        try:
            on_disk = worktree(path)
        except OSError:
            on_disk = MISSING
        provenance.append((path, freeze, committed, on_disk))
    provenance = tuple(provenance)

    if sha:
        try:
            disk = worktree(SHARD)
        except OSError:
            disk = MISSING
        reach = {}
        for p, _r, _f in REACH:
            try:                                  # so L8's unreadable arm is live code, not dead
                reach[p] = blob("%s:%s" % (sha, p))
            except SystemExit:
                reach[p] = None
        return (blob("%s^:%s" % (sha, LIVE)), blob("%s:%s" % (sha, LIVE)),
                blob("%s:%s" % (sha, SHARD)), blob("%s:%s" % (sha, CLAUDE)),
                "the trim commit %s" % sha[:7], sha, disk, reach, lineage, provenance)
    reach = {}
    for p, _r, _f in REACH:
        try:
            reach[p] = worktree(p)
        except OSError:
            reach[p] = None
    return (blob("HEAD:%s" % LIVE), worktree(LIVE), worktree(SHARD), worktree(CLAUDE),
            "HEAD vs the working tree (trim not yet committed)", None, NA, reach, lineage,
            provenance)


def self_test(before, after, shard, claude, sha, reach, lineage, provenance):
    _, ar, _ = zones(after)
    sf, sr, _ = zones(shard)
    purpose = next(ln for ln in zones(before)[0].splitlines() if ln.startswith("**Purpose:**"))

    def sub_in_shard(o, n, count=1):
        assert o in shard, "self-test fixture missing: %r" % o[:40]
        return shard.replace(o, n, count)

    assert "−" in "".join(sr), "self-test fixture missing: no U+2212 in the archived span"
    assert "−" not in sf, "fixture broken: M9 must mutate a RECORD, not the shard banner"

    # Every clause a mutant rewrites must be unambiguous in every text that carries it.
    CL216  = "**N ≤ 216** → `SESSION_NOTES-through-S216.md`"
    CL220  = "**217 ≤ N ≤ 220** → `SESSION_NOTES-S220-through-S217.md`"
    CL224  = "**221 ≤ N ≤ 224** → `SESSION_NOTES-S224-through-S221.md`"
    CL227  = "**225 ≤ N ≤ 227** → `SESSION_NOTES-S227-through-S225.md`"
    CL231  = "**228 ≤ N ≤ 231** → `SESSION_NOTES-S231-through-S228.md`"
    CL235  = "**232 ≤ N ≤ 235** → `SESSION_NOTES-S235-through-S232.md`"
    CLLIVE = "**N ≥ 236** → `SESSION_NOTES.md`"
    for cl in (CL216, CL220, CL224, CL227, CL231, CL235, CLLIVE):
        for name, text in (("POINTER", POINTER), ("BANNER", BANNER),
                           ("live file", after), ("shard", shard), ("CLAUDE.md", claude)):
            assert text.count(cl) == 1, ("self-test fixture %r occurs %d times in %s (want 1)"
                                         % (cl[:28], text.count(cl), name))

    def rewrite(pairs, texts):
        """Apply the same clause rewrites to every text that carries the table."""
        out = []
        for t in texts:
            for o, n in pairs:
                t = t.replace(o, n, 1)
            out.append(t)
        return out

    # --- L5 fixtures. Each rewrites the DECLARATION and the artifact together, so the assertion
    #     that pins them by equality (L2 for the pointer, L6 for the banner) stays satisfied and
    #     L5 is the only one left able to object.
    m18_b, m18_s = rewrite([(CLLIVE, "**N ≥ 232** → `SESSION_NOTES.md`")], [BANNER, shard])
    m19_b, m19_s = rewrite([(CL235, "**231 ≤ N ≤ 235** → `SESSION_NOTES-S235-through-S232.md`")],
                           [BANNER, shard])
    m20_p, m20_a = rewrite([(CLLIVE, "**N ≥ 232** → `SESSION_NOTES.md`")], [POINTER, after])
    m21_p, m21_a = rewrite([(CL235, "**233 ≤ N ≤ 235** → `SESSION_NOTES-S235-through-S232.md`")],
                           [POINTER, after])
    swap = [(CL231, "**228 ≤ N ≤ 231** → `SESSION_NOTES-S235-through-S232.md`"),
            (CL235, "**232 ≤ N ≤ 235** → `SESSION_NOTES-S231-through-S228.md`")]
    m22_b, m22_s = rewrite(swap, [BANNER, shard])
    m23_p, m23_a = rewrite(swap, [POINTER, after])

    # M24/M25/M38/M39/M47 rewrite ROUTING as well, so even the declaration is self-consistent.
    short = [(CL235, "**232 ≤ N ≤ 234** → `SESSION_NOTES-S235-through-S232.md`"),
             (CLLIVE, "**N ≥ 235** → `SESSION_NOTES.md`")]
    m24_p, m24_b, m24_a, m24_s, m24_c = rewrite(short, [POINTER, BANNER, after, shard, claude])
    m24_r = ((None, 216, "SESSION_NOTES-through-S216.md"),
             (217, 220, "SESSION_NOTES-S220-through-S217.md"),
             (221, 224, "SESSION_NOTES-S224-through-S221.md"),
             (225, 227, "SESSION_NOTES-S227-through-S225.md"),
             (228, 231, "SESSION_NOTES-S231-through-S228.md"),
             (232, 234, "SESSION_NOTES-S235-through-S232.md"),
             (235, None, "SESSION_NOTES.md"))
    front = [(CL216, "**N ≤ 100** → `SESSION_NOTES-through-S216.md`"),
             (CL220, "**101 ≤ N ≤ 220** → `SESSION_NOTES-S220-through-S217.md`")]
    m25_p, m25_b, m25_a, m25_s, m25_c = rewrite(front, [POINTER, BANNER, after, shard, claude])
    m25_r = ((None, 100, "SESSION_NOTES-through-S216.md"),
             (101, 220, "SESSION_NOTES-S220-through-S217.md"),
             (221, 224, "SESSION_NOTES-S224-through-S221.md"),
             (225, 227, "SESSION_NOTES-S227-through-S225.md"),
             (228, 231, "SESSION_NOTES-S231-through-S228.md"),
             (232, 235, "SESSION_NOTES-S235-through-S232.md"),
             (236, None, "SESSION_NOTES.md"))
    gap = [(CL224, "**221 ≤ N ≤ 223** → `SESSION_NOTES-S224-through-S221.md`")]
    m38_p, m38_b, m38_a, m38_s, m38_c = rewrite(gap, [POINTER, BANNER, after, shard, claude])
    m38_r = ((None, 216, "SESSION_NOTES-through-S216.md"),
             (217, 220, "SESSION_NOTES-S220-through-S217.md"),
             (221, 223, "SESSION_NOTES-S224-through-S221.md"),
             (225, 227, "SESSION_NOTES-S227-through-S225.md"),
             (228, 231, "SESSION_NOTES-S231-through-S228.md"),
             (232, 235, "SESSION_NOTES-S235-through-S232.md"),
             (236, None, "SESSION_NOTES.md"))
    over = [(CL224, "**221 ≤ N ≤ 225** → `SESSION_NOTES-S224-through-S221.md`")]
    shape = [(CL224, "**N ≤ 224** → `SESSION_NOTES-S224-through-S221.md`")]
    m39_p, m39_b, m39_a, m39_s, m39_c = rewrite(over, [POINTER, BANNER, after, shard, claude])
    m39_r = ((None, 216, "SESSION_NOTES-through-S216.md"),
             (217, 220, "SESSION_NOTES-S220-through-S217.md"),
             (221, 225, "SESSION_NOTES-S224-through-S221.md"),
             (225, 227, "SESSION_NOTES-S227-through-S225.md"),
             (228, 231, "SESSION_NOTES-S231-through-S228.md"),
             (232, 235, "SESSION_NOTES-S235-through-S232.md"),
             (236, None, "SESSION_NOTES.md"))
    m47_p, m47_b, m47_a, m47_s, m47_c = rewrite(shape, [POINTER, BANNER, after, shard, claude])
    m47_r = ((None, 216, "SESSION_NOTES-through-S216.md"),
             (217, 220, "SESSION_NOTES-S220-through-S217.md"),
             (None, 224, "SESSION_NOTES-S224-through-S221.md"),
             (225, 227, "SESSION_NOTES-S227-through-S225.md"),
             (228, 231, "SESSION_NOTES-S231-through-S228.md"),
             (232, 235, "SESSION_NOTES-S235-through-S232.md"),
             (236, None, "SESSION_NOTES.md"))

    # M16/M17 move ONE WHOLE RECORD across the boundary. ar[-1] is the oldest retained record and
    # sr[0] the newest archived one, so both mutants keep the newest-on-top order intact — which is
    # exactly why L1 and L3 cannot see them and L4 must.
    m16_after, m16_shard = after.replace(ar[-1], "", 1), sf + ar[-1] + "".join(sr)
    m17_after, m17_shard = after + sr[0], shard.replace(sr[0], "", 1)

    # --- L8 fixtures. Each mutates ONE of the four out-of-reach files.
    def reach_with(path, old, new, count=1):
        assert reach[path].count(old) >= 1, "self-test fixture missing in %s: %r" % (path, old[:50])
        r = dict(reach)
        r[path] = r[path].replace(old, new, count)
        return r
    m31 = reach_with(README, "older in the six shards above", "older in the five shards above")
    m32 = reach_with(README, REACH[0][1][0], "")
    m33 = reach_with(CONVENTIONS, "**Six instances so far**", "**Five instances so far**")
    m34 = reach_with(CONVENTIONS, "`SESSION_NOTES-S235-through-S232.md` (Session 239",
                     "`SESSION_NOTES-S234-through-S232.md` (Session 239")
    m41 = reach_with(BACKLOG, "there are now **six** unwatched shards",
                     "there are now **five** unwatched shards")
    # M42 removes the new shard's NAME from BACKLOG.md while leaving its size figure in place. It
    # therefore trips L8/set AND L12/prose (whose declared literal carries the name); recorded in
    # the coverage block rather than contrived into an L8-only form — M45 and M46 already give
    # L8/set mutants of its own.
    m42 = reach_with(BACKLOG, "`SESSION_NOTES-S235-through-S232.md` (1,057 lines)",
                     "the newest shard (1,057 lines)")

    # --- Sub-clause fixtures inherited from the fourth trim's adversarial review.
    m43 = dict(reach)                                    # CLAUDE.md: table intact, count words stale
    m43[CLAUDE] = (m43[CLAUDE]
                   .replace("**Trimmed six times (Sessions 222, 224, 228, 231, 235, 239):**",
                            "**Trimmed five times (Sessions 222, 224, 228, 231, 235):**", 1)
                   .replace("Retired records live in **six** write-once shards",
                            "Retired records live in **five** write-once shards", 1)
                   .replace("grep *all six*", "grep *all five*", 1)
                   .replace("there are SIX, and a lookup must consult all of them",
                            "there are FIVE, and a lookup must consult all of them", 1))
    # forbidden ALONE: the required string stays, the falsified one comes back beside it.
    m44 = reach_with(CONVENTIONS, "**Six instances so far**",
                     "**Six instances so far** — it said **Five instances so far** before this cut")
    # set ALONE: an ANCESTOR's name typo'd, so required and forbidden are both untouched.
    m45 = reach_with(CONVENTIONS, "`SESSION_NOTES-S224-through-S221.md` (Session 228",
                     "`SESSION_NOTES-S224-through-S220.md` (Session 228")
    # set, via the lookahead: drop an ancestor's own repo-map line and leave its `.verify.sh` line.
    m46 = reach_with(README,
                     "  SESSION_NOTES-S224-through-S221.md    # frozen SESSION_NOTES records, Sessions 224->221 (grep it; do not Read it)\n",
                     "")
    # L9's third arm: git knows the file but no commit that added it.
    m48 = tuple((p, None, d) if i == 0 else (p, c, d)
                for i, (p, c, d) in enumerate(lineage))
    # L8's unreadable arm.
    m49 = {k: v for k, v in reach.items() if k != README}
    m49[README] = None
    # required ALONE: a declared string reworded so no forbidden string appears and the shard
    # name set stays complete.
    m50 = reach_with(CONVENTIONS, "**Six instances so far**", "**6 instances so far**")

    # --- L9 fixtures. Same shape as L7's, one level out: the ANCESTOR shards on disk.
    def lineage_with(idx, mutate):
        out = list(lineage)
        path, committed, on_disk = out[idx]
        out[idx] = (path, committed, mutate(on_disk))
        return tuple(out)
    m35 = lineage_with(0, lambda t: t[:20000])
    m36 = lineage_with(1, lambda _t: MISSING)
    m37 = lineage_with(2, lambda t: t.replace("e", "3", 1))

    # M51 — L2/b3's narrowed form, and the only mutant that reaches it. A front-matter line is
    # COPIED into the banner (and into the declaration, so L6 is satisfied) and LEFT IN PLACE in
    # the live front matter, so b2's SURVIVAL arm has nothing to say and b1 sees an untouched
    # after_front.
    #
    # IT REPLACES A BANNER LINE RATHER THAN APPENDING ONE, and that is not cosmetic. The fifth
    # trim's M51 appended, which under THIS proof also changes the shard's line count — so L12
    # catches it, and b3 is left with no uniquely-catching mutant of its own. Measured, not
    # predicted: the neuter loop reported M51 caught with L2 disabled. A mutant must isolate the
    # arm it exists for; making it line-count-neutral is what restores that.
    LINE = "where the fifth trim had left it. Expect this at every boundary, in both directions."
    assert BANNER.count(LINE) == 1 and purpose not in BANNER, "M51 fixture broken"
    m51_b = BANNER.replace(LINE, purpose, 1)
    m51_s = m51_b + "".join(sr)

    # M52 — L5/4's UNREADABLE arm, alone. An ancestor shard's filename is typo'd in the
    # declaration AND in every prose copy AND in all four REACH texts, so L5/1-L5/3 are
    # self-consistent and L8/set sees the same (wrong) name set the routing table does.
    TYPO = ("SESSION_NOTES-S220-through-S217.md", "SESSION_NOTES-S220-through-S218.md")
    m52_p, m52_b, m52_a, m52_s, m52_c = rewrite(
        [(CL220, CL220.replace(*TYPO))], [POINTER, BANNER, after, shard, claude])
    m52_r = tuple((lo, hi, d.replace(*TYPO)) for lo, hi, d in ROUTING)
    m52_reach = {k: (v.replace(*TYPO) if v is not None else None) for k, v in reach.items()}

    # M53/M54/M55 — L10's three arms, one each.
    def provenance_with(idx, committed=..., disk=...):
        out = list(provenance)
        c, d = out[idx][2], out[idx][3]
        out[idx] = (out[idx][0], out[idx][1],
                    c if committed is ... else committed,
                    d if disk is ... else disk)
        return tuple(out)
    m53 = provenance_with(0, committed=None)                       # declared freeze holds no blob
    m54 = provenance_with(1, disk=MISSING)                         # proof deleted from the tree
    m55 = provenance_with(4, disk=provenance[4][3][:12000])        # proof truncated on disk

    # M56/M57/M58/M59 — L11's four arms, one each.
    trig, targ, floor, texts = POLICY
    m56_pol = (5000, targ, floor, texts)
    m57_pol = (trig, 500, floor, texts)
    m58_pol = (trig, targ, 9, texts)
    m59_c = claude.replace("Fire a new trim when the live file exceeds **1,500 lines**",
                           "Fire a new trim when the live file feels too long", 1)

    # --- NEW at this trim: L12's six arms, nine mutants. -------------------------------------
    # M60-M63 and M68 move ONE declared integer and leave every prose copy alone, so each numeric arm is
    # reached by itself and the prose half stays satisfied (it measures the artifacts, never the
    # declaration). M64-M67 do the opposite: they move a FIGURE IN THE PROSE together with every
    # declaration that pins that prose by equality — POINTER for the pointer block, BANNER for the
    # banner, and SIZE_PROSE's own literal — so L2/b1 and L6 are satisfied and L12/prose is the
    # only assertion left able to object. That is the real-world failure this arm exists for: a
    # number typed once, then copied consistently everywhere.
    def sizes_with(**kw):
        s = dict(SIZES)
        s.update(kw)
        return s

    def prose_with(old, new):
        assert any(old in l for _w, l, _f, _k in SIZE_PROSE), "fixture missing in SIZE_PROSE: %r" % old
        return tuple((w, l.replace(old, new, 1), f, k) for w, l, f, k in SIZE_PROSE)

    m60 = sizes_with(archived_headings=5)
    m61 = sizes_with(archived_lines=1014)
    m62 = sizes_with(shard_total=1067)
    # M63 mis-states the cap CONSISTENTLY — in the declaration, in the banner and in the
    # declared literal — so the prose half is satisfied and the cap arm is the only one left
