print("         held against %d declared integers and %d prose claims in %d texts"
      % (len(SIZES), len(SIZE_PROSE), len({w for w, _l, _f, _k in SIZE_PROSE})))
print("front  : pointer insertion + %d declared substitutions, all checked by exact equality"
      % len(FRONT_SUBST))
